insert into public.site_settings (id, site_name, logo_header_url, logo_footer_url, phones, whatsapp_number, whatsapp_greeting, email, social_links, branches, working_hours, opening_hours_spec, nav_links, footer) values
  (1, '{"ar":"د. أحمد شولح","en":"Dr. Ahmed Shoulah"}'::jsonb, '/media/brand/logo-horizontal.png', '/media/brand/logo-stacked.png', '[{"value":"+201000000000","display":"+20 100 000 0000"},{"value":"+201200000000","display":"+20 120 000 0000"}]'::jsonb, '201000000000', '{"ar":"مرحبًا د. أحمد، أرغب في حجز استشارة.","en":"Hello Dr. Ahmed, I would like to book a consultation."}'::jsonb, 'info@example.com', '[{"network":"Facebook","url":"https://www.facebook.com/your-page"},{"network":"Instagram","url":"https://www.instagram.com/your-account"},{"network":"YouTube","url":"https://www.youtube.com/@your-channel"},{"network":"TikTok","url":"https://www.tiktok.com/@your-account"}]'::jsonb, '[{"id":"main","name":{"ar":"العيادة الرئيسية — مدينة نصر","en":"Main Clinic — Nasr City"},"address":{"ar":"12 شارع عباس العقاد، مدينة نصر، القاهرة، مصر","en":"12 Abbas El Akkad St., Nasr City, Cairo, Egypt"},"phone":"+201000000000","map_embed_url":"","directions_url":"","lat":30.0566,"lng":31.3301},{"id":"heliopolis","name":{"ar":"فرع مصر الجديدة","en":"Heliopolis Branch"},"address":{"ar":"45 شارع الميرغني، مصر الجديدة، القاهرة، مصر","en":"45 El Merghany St., Heliopolis, Cairo, Egypt"},"phone":"+201200000000","map_embed_url":"","directions_url":"","lat":30.0911,"lng":31.3402}]'::jsonb, '[{"days":{"ar":"السبت – الأربعاء","en":"Saturday – Wednesday"},"time":{"ar":"5:00 م – 10:00 م","en":"5:00 PM – 10:00 PM"}},{"days":{"ar":"الخميس","en":"Thursday"},"time":{"ar":"12:00 م – 4:00 م","en":"12:00 PM – 4:00 PM"}},{"days":{"ar":"الجمعة","en":"Friday"},"time":{"ar":"مغلق","en":"Closed"}}]'::jsonb, '[{"days":["Saturday","Sunday","Monday","Tuesday","Wednesday"],"opens":"17:00","closes":"22:00"},{"days":["Thursday"],"opens":"12:00","closes":"16:00"}]'::jsonb, '[{"label":{"ar":"الرئيسية","en":"Home"},"href":"/","visible":true},{"label":{"ar":"عن الدكتور","en":"About"},"href":"/about","visible":true},{"label":{"ar":"الخدمات","en":"Services"},"href":"/services","visible":true},{"label":{"ar":"آراء المرضى","en":"Reviews"},"href":"/reviews","visible":true},{"label":{"ar":"الفيديوهات","en":"Videos"},"href":"/videos","visible":true},{"label":{"ar":"المقالات","en":"Articles"},"href":"/articles","visible":true},{"label":{"ar":"تواصل معنا","en":"Contact"},"href":"/contact","visible":true}]'::jsonb, '{"about":{"ar":"استشاري الجراحة العامة والمناظير، يقدّم رعاية جراحية آمنة وحديثة بأقل تدخل جراحي ممكن، مع متابعة شخصية لكل مريض.","en":"Consultant of general and laparoscopic surgery offering safe, modern, minimally invasive surgical care with personal follow-up for every patient."},"copyright":{"ar":"© {year} {name}. جميع الحقوق محفوظة.","en":"© {year} {name}. All rights reserved."},"disclaimer":{"ar":"المعلومات الواردة في هذا الموقع للتوعية العامة ولا تُغني عن الاستشارة الطبية.","en":"The information on this website is for general awareness and does not replace a medical consultation."},"quick_links":[{"label":{"ar":"الرئيسية","en":"Home"},"href":"/"},{"label":{"ar":"عن الدكتور","en":"About"},"href":"/about"},{"label":{"ar":"الخدمات","en":"Services"},"href":"/services"},{"label":{"ar":"آراء المرضى","en":"Reviews"},"href":"/reviews"},{"label":{"ar":"الفيديوهات","en":"Videos"},"href":"/videos"},{"label":{"ar":"المقالات","en":"Articles"},"href":"/articles"},{"label":{"ar":"تواصل معنا","en":"Contact"},"href":"/contact"}]}'::jsonb)
insert into public.doctors_profile (id, name, short_name, title, credentials, image_alt, photo_url, message_photo_url, message, timeline, certificates, expertise, intro_video, headings) values
  (1, '{"ar":"د. أحمد شولح","en":"Dr. Ahmed Shoulah"}'::jsonb, '{"ar":"د. أحمد","en":"Dr. Ahmed"}'::jsonb, '{"ar":"استشاري الجراحة العامة والمناظير","en":"Consultant of General & Laparoscopic Surgery"}'::jsonb, '{"ar":"دكتوراه الجراحة · عضوية الكلية الملكية للجراحين (إنجلترا)","en":"MD (Surgery) · MRCS (England)"}'::jsonb, '{"ar":"صورة د. أحمد شولح، استشاري الجراحة العامة والمناظير","en":"Portrait of Dr. Ahmed Shoulah, consultant of general and laparoscopic surgery"}'::jsonb, '/media/doctor/portrait.jpg', '/media/doctor/message.jpg', '{"eyebrow":{"ar":"رسالة من الطبيب","en":"A message from the doctor"},"title":{"ar":"الجراحة مسؤولية قبل أن تكون مهنة","en":"Surgery is a responsibility before it is a profession"},"paragraphs":[{"ar":"حين يدخل المريض عيادتي، فهو يأتمنني على ما هو أكثر من التشخيص؛ يأتمنني على صحته ووقته، وغالبًا على مخاوفه. ولا أستهين بهذه الثقة أبدًا.","en":"When a patient walks into my clinic, they are trusting me with more than a diagnosis. They are trusting me with their health, their time and often their fears. I never take that trust lightly."},{"ar":"تعلّمت عبر السنين أن أفضل النتائج الجراحية تبدأ قبل غرفة العمليات بوقت طويل: بالإصغاء الجيد، والشرح الصادق، وخطة نبنيها معًا. وأحيانًا تكون أفضل نصيحة هي أنك لا تحتاج إلى جراحة على الإطلاق.","en":"Over the years I have learned that the best surgical outcomes start long before the operating room: with careful listening, an honest explanation and a plan we build together. Sometimes the best advice is that you do not need surgery at all."},{"ar":"وعندما تكون الجراحة هي الخيار الصحيح، ألتزم بإجرائها بأدق التقنيات وأقلها تدخلًا، وبأن أبقى بجانبك حتى تتعافى تمامًا.","en":"When surgery is the right choice, I am committed to performing it with the most precise, least invasive technique available, and to staying by your side until you have fully recovered."}],"signature":{"ar":"د. أحمد شولح","en":"Dr. Ahmed Shoulah"}}'::jsonb, '[{"year":"2004","title":{"ar":"بكالوريوس الطب والجراحة","en":"Bachelor of Medicine & Surgery (MBBCh)"},"place":{"ar":"كلية الطب، جامعة القاهرة، بتقدير امتياز مع مرتبة الشرف","en":"Faculty of Medicine, Cairo University, with honours"}},{"year":"2009","title":{"ar":"ماجستير الجراحة العامة","en":"Master’s Degree in General Surgery (MSc)"},"place":{"ar":"مستشفيات جامعة القاهرة (قصر العيني)","en":"Cairo University Hospitals (Kasr Al Ainy)"}},{"year":"2011","title":{"ar":"عضوية الكلية الملكية للجراحين (MRCS)","en":"Membership of the Royal College of Surgeons (MRCS)"},"place":{"ar":"الكلية الملكية للجراحين بإنجلترا، المملكة المتحدة","en":"Royal College of Surgeons of England, United Kingdom"}},{"year":"2014","title":{"ar":"دكتوراه الجراحة العامة","en":"Doctorate in General Surgery (MD)"},"place":{"ar":"جامعة القاهرة","en":"Cairo University"}},{"year":"2016","title":{"ar":"زمالة جراحات المناظير المتقدمة","en":"Fellowship in Advanced Laparoscopic Surgery"},"place":{"ar":"مركز دولي للتدريب على الجراحة بأقل تدخل، أوروبا","en":"International minimally invasive surgery training centre, Europe"}},{"year":"2018","title":{"ar":"استشاري الجراحة العامة والمناظير","en":"Consultant of General & Laparoscopic Surgery"},"place":{"ar":"كبرى المستشفيات الخاصة والجامعية بالقاهرة","en":"Leading private and university hospitals in Cairo"}}]'::jsonb, '[{"title":{"ar":"دكتوراه الجراحة العامة","en":"MD in General Surgery"},"issuer":{"ar":"جامعة القاهرة","en":"Cairo University"},"year":"2014","image_url":"/media/certificates/certificate-1.jpg"},{"title":{"ar":"عضوية الكلية الملكية للجراحين (MRCS)","en":"Membership of the Royal College of Surgeons (MRCS)"},"issuer":{"ar":"الكلية الملكية للجراحين بإنجلترا","en":"Royal College of Surgeons of England"},"year":"2011","image_url":"/media/certificates/certificate-2.jpg"},{"title":{"ar":"زمالة جراحات المناظير المتقدمة","en":"Advanced Laparoscopic Surgery Fellowship"},"issuer":{"ar":"مركز تدريب دولي","en":"International training centre"},"year":"2016","image_url":"/media/certificates/certificate-3.jpg"},{"title":{"ar":"شهادة جراحات الشرج بالليزر","en":"Laser Proctology Certification"},"issuer":{"ar":"دورة أوروبية متخصصة","en":"European proctology course"},"year":"2019","image_url":"/media/certificates/certificate-4.jpg"},{"title":{"ar":"جراحة الغدة الدرقية ومراقبة الأعصاب","en":"Thyroid Surgery & Nerve Monitoring"},"issuer":{"ar":"ورشة دولية لجراحة الغدد الصماء","en":"International endocrine surgery workshop"},"year":"2020","image_url":"/media/certificates/certificate-5.jpg"},{"title":{"ar":"دعم الحياة المتقدم للإصابات (ATLS)","en":"Advanced Trauma Life Support (ATLS)"},"issuer":{"ar":"الكلية الأمريكية للجراحين","en":"American College of Surgeons"},"year":"2022","image_url":"/media/certificates/certificate-6.jpg"}]'::jsonb, '[{"icon":"scan-line","title":{"ar":"جراحات المناظير المتقدمة","en":"Advanced laparoscopic surgery"},"description":{"ar":"المرارة والزائدة الدودية والارتجاع والمنظار التشخيصي من خلال فتحات صغيرة.","en":"Gallbladder, appendix, reflux and diagnostic laparoscopy performed through keyhole incisions."},"href":"/services#laparoscopic"},{"icon":"shield-plus","title":{"ar":"الفتق وجدار البطن","en":"Hernia & abdominal wall"},"description":{"ar":"الفتق الإربي والسُّري والجراحي والمرتجع، وإعادة بناء جدار البطن.","en":"Inguinal, umbilical, incisional and recurrent hernias, plus abdominal wall reconstruction."},"href":"/services#hernia"},{"icon":"stethoscope","title":{"ar":"جراحات الشرج والليزر","en":"Anorectal & laser surgery"},"description":{"ar":"علاج حديث قليل الألم للبواسير والشرخ والناسور والناسور العصعصي.","en":"Modern, low-pain treatment of hemorrhoids, fissures, fistulas and pilonidal sinus."},"href":"/services#anorectal"},{"icon":"graduation-cap","title":{"ar":"الغدة الدرقية والغدد الصماء","en":"Thyroid & endocrine surgery"},"description":{"ar":"جراحات الغدة الدرقية والجار درقية والكظرية مع الحفاظ على الأعصاب.","en":"Thyroid, parathyroid and adrenal surgery using nerve-sparing techniques."},"href":"/services#endocrine"},{"icon":"ambulance","title":{"ar":"جراحات الطوارئ","en":"Emergency surgery"},"description":{"ar":"تعامل سريع واحترافي مع التهاب الزائدة الحاد وانسداد الأمعاء وطوارئ البطن.","en":"Rapid, expert management of acute appendicitis, bowel obstruction and abdominal emergencies."},"href":"/services#laparoscopic"},{"icon":"clock","title":{"ar":"جراحات اليوم الواحد","en":"Day-case surgery"},"description":{"ar":"عمليات مختارة بعناية مع الخروج في اليوم نفسه وتعافٍ مريح في المنزل.","en":"Carefully selected procedures with same-day discharge and a comfortable recovery at home."},"href":"/services"}]'::jsonb, '{"title":{"ar":"فيديو تعريفي عن د. أحمد شولح","en":"Introduction to Dr. Ahmed Shoulah"},"url":"","thumbnail_url":"/media/videos/intro.jpg"}'::jsonb, '{"career":{"eyebrow":{"ar":"المسيرة المهنية والمؤهلات","en":"Career & qualifications"},"title":{"ar":"مسيرة قائمة على العلم والتميز","en":"A journey built on learning and excellence"}},"intro_video":{"eyebrow":{"ar":"فيديو تعريفي","en":"Introductory video"},"title":{"ar":"تعرّف على الطبيب في دقيقتين","en":"Get to know the doctor in two minutes"},"description":{"ar":"يتحدث د. أحمد عن فلسفته في الجراحة، وسلامة المرضى، وما يمكنك توقعه في زيارتك الأولى.","en":"Dr. Ahmed talks about his approach to surgery, patient safety and what you can expect from your first visit."}},"expertise":{"eyebrow":{"ar":"مجالات الخبرة","en":"Areas of expertise"},"title":{"ar":"خبرات جراحية متخصصة","en":"Specialised surgical expertise"},"cta":{"ar":"عرض جميع الخدمات","en":"View all services"}},"certificates":{"eyebrow":{"ar":"الشهادات والاعتمادات","en":"Certificates & accreditations"},"title":{"ar":"مؤهلات معتمدة دوليًا","en":"Internationally recognised qualifications"}},"achievements":{"eyebrow":{"ar":"إنجازات","en":"Achievements"},"title":{"ar":"سجلّ إنجازات يمكنك الوثوق به","en":"A track record you can trust"}}}'::jsonb)
insert into public.hero_sections (page, eyebrow, title, description, image_url, buttons, cta_band, meta_title, meta_description) values
  ('home', '{"ar":"","en":""}'::jsonb, '{"ar":"جراحة *عامة ومناظير* متقدمة بلمسة رعاية شخصية","en":"Advanced *general & laparoscopic* surgery with a personal touch"}'::jsonb, '{"ar":"بخبرة جراحية تتجاوز 18 عامًا، يقدّم د. أحمد شولح حلولًا آمنة بأقل تدخل جراحي لحالات المرارة والفتق والشرج والغدة الدرقية، من أول استشارة وحتى التعافي الكامل.","en":"With over 18 years of surgical experience, Dr. Ahmed Shoulah offers safe, minimally invasive solutions for gallbladder, hernia, anorectal and thyroid conditions, from the first consultation to full recovery."}'::jsonb, null, '[{"label":{"ar":"احجز الآن","en":"Book Now"},"href":"/contact","style":"primary"},{"label":{"ar":"خدماتنا","en":"Our Services"},"href":"/services","style":"outline"}]'::jsonb, '{"eyebrow":{"ar":"احجز استشارتك","en":"Book your consultation"},"title":{"ar":"مستعد لاتخاذ أول خطوة نحو التعافي؟","en":"Ready to take the first step toward recovery?"},"text":{"ar":"احجز استشارتك اليوم واحصل على خطة واضحة وصادقة مصممة لحالتك.","en":"Book your consultation today and get a clear, honest plan tailored to your condition."}}'::jsonb, '{"ar":"د. أحمد شولح | استشاري الجراحة العامة والمناظير","en":"Dr. Ahmed Shoulah | Consultant General & Laparoscopic Surgeon"}'::jsonb, '{"ar":"استشاري الجراحة العامة وجراحات المناظير والفتق والشرج والغدد الصماء بخبرة تتجاوز 18 عامًا. احجز استشارتك الآن عبر الموقع أو واتساب.","en":"Consultant of general, laparoscopic, hernia, anorectal and endocrine surgery with 18+ years of experience. Book your consultation online or via WhatsApp."}'::jsonb),
  ('about', '{"ar":"عن الدكتور","en":"About the doctor"}'::jsonb, '{"ar":"د. أحمد شولح","en":"Dr. Ahmed Shoulah"}'::jsonb, '{"ar":"استشاري الجراحة العامة والمناظير، يجمع بين التميز الأكاديمي والتدريب الدولي والاهتمام الشخصي بكل مريض.","en":"Consultant of general & laparoscopic surgery, combining academic excellence, international training and a deeply personal approach to patient care."}'::jsonb, null, '[{"label":{"ar":"احجز الآن","en":"Book Now"},"href":"/contact","style":"primary"},{"label":{"ar":"واتساب","en":"WhatsApp"},"href":"whatsapp","style":"outline"}]'::jsonb, '{"eyebrow":{"ar":"احجز استشارتك","en":"Book your consultation"},"title":{"ar":"لنناقش حالتك معًا","en":"Let’s discuss your case together"},"text":{"ar":"كل مريض حالة فريدة. احجز استشارة وسيراجع د. أحمد حالتك والخيارات المتاحة بنفسه.","en":"Every patient is unique. Book a consultation and Dr. Ahmed will personally review your condition and options."}}'::jsonb, '{"ar":"عن الدكتور","en":"About the Doctor"}'::jsonb, '{"ar":"تعرّف على د. أحمد شولح: المؤهلات العلمية، والمسيرة المهنية، والشهادات، ومجالات الخبرة في الجراحة العامة وجراحات المناظير.","en":"Meet Dr. Ahmed Shoulah: qualifications, career milestones, certificates and areas of expertise in general and laparoscopic surgery."}'::jsonb),
  ('services', '{"ar":"خدماتنا","en":"Our services"}'::jsonb, '{"ar":"رعاية جراحية متخصصة","en":"Specialised surgical care"}'::jsonb, '{"ar":"أربعة مجالات متخصصة تغطي أكثر حالات الجراحة العامة شيوعًا، تُعالج بتقنيات حديثة وبأقل تدخل جراحي.","en":"Four specialised fields covering the most common general surgery conditions, treated with modern, minimally invasive techniques."}'::jsonb, null, '[{"label":{"ar":"احجز الآن","en":"Book Now"},"href":"/contact","style":"primary"},{"label":{"ar":"واتساب","en":"WhatsApp"},"href":"whatsapp","style":"outline"}]'::jsonb, '{"eyebrow":{"ar":"احجز استشارتك","en":"Book your consultation"},"title":{"ar":"لست متأكدًا من العملية التي تحتاجها؟","en":"Not sure which procedure you need?"},"text":{"ar":"أرسل تقاريرك عبر واتساب أو احجز استشارة، وسنرشدك إلى العلاج المناسب.","en":"Send us your reports on WhatsApp or book a consultation, and we will guide you to the right treatment."}}'::jsonb, '{"ar":"الخدمات الجراحية","en":"Surgical Services"}'::jsonb, '{"ar":"جراحات المناظير والجهاز الهضمي، وإصلاح الفتق وجدار البطن، وجراحات الشرج والمستقيم، وجراحات الغدة الدرقية والغدد الصماء بأحدث التقنيات وبأقل تدخل جراحي.","en":"Laparoscopic & GI surgery, hernia and abdominal wall repair, anorectal surgery and thyroid & endocrine surgery with modern, minimally invasive techniques."}'::jsonb),
  ('reviews', '{"ar":"آراء المرضى","en":"Patient reviews"}'::jsonb, '{"ar":"قصص حقيقية… وتعافٍ حقيقي","en":"Real stories, real recoveries"}'::jsonb, '{"ar":"ما يقوله مرضانا عن تجربتهم، من الاستشارة الأولى حتى التعافي الكامل.","en":"What our patients say about their experience, from the first consultation to full recovery."}'::jsonb, null, '[{"label":{"ar":"احجز الآن","en":"Book Now"},"href":"/contact","style":"primary"},{"label":{"ar":"واتساب","en":"WhatsApp"},"href":"whatsapp","style":"outline"}]'::jsonb, '{"eyebrow":{"ar":"احجز استشارتك","en":"Book your consultation"},"title":{"ar":"كن قصة النجاح التالية","en":"Become our next success story"},"text":{"ar":"انضم إلى آلاف المرضى الذين وثقوا بالدكتور أحمد في رحلة علاجهم وتعافيهم.","en":"Join thousands of patients who trusted Dr. Ahmed with their surgery and recovery."}}'::jsonb, '{"ar":"آراء المرضى","en":"Patient Reviews"}'::jsonb, '{"ar":"اقرأ تجارب مرضى أجروا جراحات المرارة والفتق والشرج والغدة الدرقية مع د. أحمد شولح.","en":"Read the experiences of patients treated by Dr. Ahmed Shoulah for gallbladder, hernia, anorectal and thyroid surgery."}'::jsonb),
  ('videos', '{"ar":"مكتبة الفيديو","en":"Video library"}'::jsonb, '{"ar":"تعرّف على حالتك في دقائق","en":"Learn about your condition in minutes"}'::jsonb, '{"ar":"فيديوهات قصيرة يقدمها الطبيب تجيب عن أكثر أسئلة المرضى شيوعًا.","en":"Short, doctor-led videos that answer the questions patients ask most."}'::jsonb, null, '[{"label":{"ar":"احجز الآن","en":"Book Now"},"href":"/contact","style":"primary"},{"label":{"ar":"واتساب","en":"WhatsApp"},"href":"whatsapp","style":"outline"}]'::jsonb, '{"eyebrow":{"ar":"احجز استشارتك","en":"Book your consultation"},"title":{"ar":"لديك سؤال لم نُجب عنه؟","en":"Have a question we didn’t cover?"},"text":{"ar":"راسلنا عبر واتساب أو احجز استشارة للحصول على نصيحة مخصصة لحالتك.","en":"Message us on WhatsApp or book a consultation for advice tailored to you."}}'::jsonb, '{"ar":"فيديوهات طبية","en":"Medical Videos"}'::jsonb, '{"ar":"فيديوهات توعوية قصيرة يقدمها الطبيب لشرح الحالات الجراحية الشائعة والعمليات والتحضير لها وفترة التعافي.","en":"Short, doctor-led educational videos explaining common surgical conditions, procedures, preparation and recovery."}'::jsonb),
  ('articles', '{"ar":"المدونة الطبية","en":"Medical blog"}'::jsonb, '{"ar":"معرفة جراحية موثوقة","en":"Trusted surgical knowledge"}'::jsonb, '{"ar":"مقالات واضحة قائمة على الأدلة العلمية بقلم د. أحمد شولح، لتساعدك على فهم حالتك والخيارات المتاحة لك.","en":"Clear, evidence-based articles written by Dr. Ahmed Shoulah to help you understand your condition and your options."}'::jsonb, null, '[{"label":{"ar":"احجز الآن","en":"Book Now"},"href":"/contact","style":"primary"},{"label":{"ar":"واتساب","en":"WhatsApp"},"href":"whatsapp","style":"outline"}]'::jsonb, '{"eyebrow":{"ar":"احجز استشارتك","en":"Book your consultation"},"title":{"ar":"المعلومة هي الخطوة الأولى… والتشخيص هو التالية","en":"Information is the first step. Diagnosis is the next."},"text":{"ar":"المقالات تساعدك على الفهم، أما الاستشارة فتمنحك إجابات خاصة بحالتك.","en":"Articles help you understand; a consultation gives you answers specific to you."}}'::jsonb, '{"ar":"مقالات طبية","en":"Medical Articles"}'::jsonb, '{"ar":"مقالات طبية واضحة وقائمة على الأدلة العلمية عن الجراحة العامة والمناظير، والأعراض، وخيارات العلاج، والتعافي.","en":"Clear, evidence-based articles about general and laparoscopic surgery, symptoms, treatment options and recovery."}'::jsonb),
  ('contact', '{"ar":"التواصل والحجز","en":"Contact & booking"}'::jsonb, '{"ar":"احجز استشارتك","en":"Book your consultation"}'::jsonb, '{"ar":"املأ النموذج وسيُرسل طلبك فورًا إلى فريقنا عبر واتساب، أو تواصل معنا مباشرة عبر الهاتف.","en":"Fill in the form and your request will be sent instantly to our team on WhatsApp, or reach us directly by phone."}'::jsonb, null, '[{"label":{"ar":"احجز الآن","en":"Book Now"},"href":"#booking","style":"primary"},{"label":{"ar":"واتساب","en":"WhatsApp"},"href":"whatsapp","style":"outline"}]'::jsonb, '{"eyebrow":{"ar":"احجز استشارتك","en":"Book your consultation"},"title":{"ar":"تفضّل التحدث مباشرة؟","en":"Prefer to talk directly?"},"text":{"ar":"فريقنا متاح خلال مواعيد العمل عبر الهاتف وواتساب للإجابة عن استفساراتك.","en":"Our team is available during working hours by phone and on WhatsApp to answer your questions."}}'::jsonb, '{"ar":"تواصل واحجز","en":"Contact & Booking"}'::jsonb, '{"ar":"احجز استشارتك مع د. أحمد شولح. عناوين العيادات وأرقام الهاتف ومواعيد العمل والحجز الفوري عبر واتساب.","en":"Book a consultation with Dr. Ahmed Shoulah. Clinic addresses, phone numbers, working hours and instant booking via WhatsApp."}'::jsonb)
insert into public.page_sections (key, content) values
  ('home.about', '{"eyebrow":{"ar":"عن الدكتور","en":"About the doctor"},"title":{"ar":"جرّاح يُصغي قبل أن يُجري الجراحة","en":"A surgeon who listens before he operates"},"paragraphs":[{"ar":"د. أحمد شولح استشاري الجراحة العامة والمناظير، حاصل على درجة الدكتوراه في الجراحة العامة وعضوية الكلية الملكية للجراحين بإنجلترا (MRCS).","en":"Dr. Ahmed Shoulah is a consultant of general and laparoscopic surgery, holding a doctorate (MD) in general surgery and membership of the Royal College of Surgeons of England (MRCS)."},{"ar":"أجرى آلاف العمليات الجراحية، بدءًا من استئصال المرارة بالمنظار وإصلاح الفتق المعقّد، وصولًا إلى علاج أمراض الشرج بالليزر وجراحات الغدة الدرقية، ملتزمًا دائمًا بمبدأ واحد: العملية المناسبة، للمريض المناسب، في الوقت المناسب.","en":"He has performed thousands of procedures, from laparoscopic gallbladder removal and complex hernia repair to laser treatment of anorectal conditions and thyroid surgery, always guided by one principle: the right operation, for the right patient, at the right time."}],"points":[{"ar":"دكتوراه الجراحة العامة","en":"MD in General Surgery"},{"ar":"عضوية الكلية الملكية للجراحين بإنجلترا","en":"MRCS, Royal College of Surgeons of England"},{"ar":"زمالة جراحات المناظير المتقدمة","en":"Fellowship in Advanced Laparoscopic Surgery"}],"cta":{"ar":"المزيد عن الدكتور","en":"More about the doctor"},"video":{"title":{"ar":"تعرّف على د. أحمد شولح","en":"Meet Dr. Ahmed Shoulah"},"url":"","thumbnail_url":"/media/videos/about.jpg"}}'::jsonb),
  ('home.surgeries', '{"eyebrow":{"ar":"أبرز العمليات","en":"Major surgeries"},"title":{"ar":"عمليات متقدمة تُجرى بدقة عالية","en":"Advanced procedures performed with precision"},"description":{"ar":"تُجرى معظم العمليات بالمنظار الجراحي: جروح أصغر، وألم أقل، وعودة أسرع إلى الحياة اليومية.","en":"Most procedures are performed laparoscopically: smaller incisions, less pain and a faster return to daily life."},"cta":{"ar":"استكشف جميع الخدمات","en":"Explore all services"},"services":["laparoscopic","hernia","endocrine"]}'::jsonb),
  ('home.why', '{"eyebrow":{"ar":"لماذا د. أحمد؟","en":"Why choose Dr. Ahmed?"},"title":{"ar":"أربعة أسباب تجعل المرضى يثقون بنا","en":"Four reasons patients trust us with their surgery"},"items":[{"icon":"award","title":{"ar":"خبرة مُثبتة","en":"Proven experience"},"description":{"ar":"أكثر من 18 عامًا و8,500 عملية في الجراحة العامة والمناظير والغدد الصماء.","en":"More than 18 years and 8,500 operations across general, laparoscopic and endocrine surgery."}},{"icon":"scan-line","title":{"ar":"الأولوية للتدخل المحدود","en":"Minimally invasive first"},"description":{"ar":"نختار تقنيات المناظير والليزر كلما كان ذلك آمنًا، لألم أقل وتعافٍ أسرع.","en":"Whenever it is safe, we choose laparoscopic and laser techniques for less pain and a faster recovery."}},{"icon":"shield-check","title":{"ar":"أمان بلا تهاون","en":"Safety without compromise"},"description":{"ar":"بروتوكولات سلامة دولية، ومستشفيات معتمدة، وفريق تخدير متخصص لكل حالة.","en":"International safety protocols, accredited hospitals and a dedicated anaesthesia team for every case."}},{"icon":"hand-heart","title":{"ar":"متابعة شخصية","en":"Personal follow-up"},"description":{"ar":"تواصل مباشر مع الطبيب قبل العملية وبعدها، مع تعليمات واضحة في كل خطوة.","en":"Direct contact with the doctor before and after surgery, with clear instructions at every step."}}]}'::jsonb),
  ('home.journey', '{"eyebrow":{"ar":"رحلتك العلاجية","en":"Your patient journey"},"title":{"ar":"من الزيارة الأولى حتى التعافي الكامل","en":"From the first visit to full recovery"},"description":{"ar":"مسار واضح خطوة بخطوة، لتعرف دائمًا ما الخطوة التالية.","en":"A clear, step-by-step path so you always know what comes next."},"steps":[{"title":{"ar":"احجز استشارتك","en":"Book your consultation"},"description":{"ar":"احجز عبر الموقع أو الهاتف أو واتساب، واختر العيادة والموعد المناسبين لك. يؤكد فريقنا موعدك ويخبرك بالتقارير أو الأشعة التي يجب إحضارها.","en":"Book online, by phone or via WhatsApp and choose the clinic and time that suit you. Our team confirms your appointment and tells you which reports or scans to bring."}},{"title":{"ar":"التقييم والتشخيص","en":"Assessment & diagnosis"},"description":{"ar":"فحص شامل ومراجعة دقيقة لتاريخك المرضي، مع طلب الفحوصات اللازمة فقط عندما تضيف قيمة حقيقية للتشخيص.","en":"A thorough examination and review of your medical history, with targeted tests requested only when they add real value to your diagnosis."}},{"title":{"ar":"خطة علاج مخصصة","en":"Personalised treatment plan"},"description":{"ar":"نناقش بلغة واضحة الخيارات الجراحية وغير الجراحية والنتائج المتوقعة والمخاطر المحتملة، ونتخذ القرار الأنسب معًا.","en":"We discuss surgical and non-surgical options, expected results and possible risks in plain language, and decide on the best plan together."}},{"title":{"ar":"يوم العملية","en":"Surgery day"},"description":{"ar":"يُجري الطبيب عمليتك بنفسه في مستشفى معتمد، بدعم من فريق تخدير وتمريض متخصص.","en":"Your procedure is performed personally by the doctor in an accredited hospital, supported by a dedicated anaesthesia and nursing team."}},{"title":{"ar":"التعافي والمتابعة","en":"Recovery & follow-up"},"description":{"ar":"تعليمات خروج واضحة، وزيارات متابعة مجدولة، وتواصل مباشر متى احتجت إلينا حتى تتعافى تمامًا.","en":"Clear discharge instructions, scheduled follow-up visits and direct contact whenever you need us until you have fully recovered."}}]}'::jsonb),
  ('home.blocks', '{"reviews":{"eyebrow":{"ar":"آراء المرضى","en":"Patient reviews"},"title":{"ar":"قصص تعافٍ يرويها مرضانا","en":"Stories of recovery from our patients"},"cta":{"ar":"اقرأ جميع الآراء","en":"Read all reviews"}},"videos":{"eyebrow":{"ar":"مكتبة الفيديو","en":"Video library"},"title":{"ar":"فيديوهات قصيرة… وإجابات واضحة","en":"Short videos, clear answers"},"cta":{"ar":"شاهد جميع الفيديوهات","en":"Watch all videos"}},"articles":{"eyebrow":{"ar":"مقالات طبية","en":"Medical articles"},"title":{"ar":"معرفة تساعدك على اتخاذ القرار","en":"Knowledge that helps you decide"},"cta":{"ar":"تصفّح جميع المقالات","en":"Browse all articles"}},"faq":{"eyebrow":{"ar":"الأسئلة الشائعة","en":"FAQ"},"title":{"ar":"إجابات عن أكثر أسئلتكم شيوعًا","en":"Answers to your most common questions"},"description":{"ar":"لم تجد ما تبحث عنه؟ يسعد فريقنا بمساعدتك.","en":"Can’t find what you are looking for? Our team is happy to help."}}}'::jsonb),
  ('stats', '{"home_title":{"ar":"ثقة آلاف المرضى","en":"Trusted by thousands of patients"},"items":[{"value":12000,"suffix":"+","label":{"ar":"مريض تماثل للشفاء","en":"Recovered patients"},"icon":"users","show_on_home":true},{"value":8500,"suffix":"+","label":{"ar":"عملية جراحية ناجحة","en":"Successful surgeries"},"icon":"activity","show_on_home":true},{"value":18,"suffix":"+","label":{"ar":"عامًا من الخبرة","en":"Years of experience"},"icon":"award","show_on_home":true},{"value":35,"suffix":"+","label":{"ar":"بحث علمي ومحاضرة","en":"Publications & lectures"},"icon":"book-open","show_on_home":false}]}'::jsonb),
  ('services.blocks', '{"fields":{"eyebrow":{"ar":"التخصصات الجراحية","en":"Surgical fields"},"title":{"ar":"اختر التخصص لاستعراض العمليات","en":"Choose a specialty to explore its procedures"}},"process":{"eyebrow":{"ar":"كيف نحدد العلاج","en":"How we decide on treatment"},"title":{"ar":"منهجية تشخيص دقيقة قائمة على الدليل العلمي","en":"A careful, evidence-based diagnostic process"},"description":{"ar":"لا نوصي بالجراحة إلا عندما تكون الخيار الأفضل لك فعلًا.","en":"Surgery is recommended only when it is truly the best option for you."},"steps":[{"title":{"ar":"استشارة مفصلة","en":"Detailed consultation"},"description":{"ar":"نستمع إلى أعراضك ونراجع تاريخك المرضي والأدوية والتقارير السابقة.","en":"We listen to your symptoms and review your medical history, medications and previous reports."}},{"title":{"ar":"الفحص السريري","en":"Clinical examination"},"description":{"ar":"فحص سريري دقيق يراعي خصوصيتك لتحديد المشكلة وطبيعتها.","en":"A focused, respectful physical examination to locate and characterise the problem."}},{"title":{"ar":"فحوصات موجّهة","en":"Targeted investigations"},"description":{"ar":"نطلب الفحوصات اللازمة فقط، مثل تحاليل الدم أو السونار أو الأشعة المقطعية أو المناظير، لتأكيد التشخيص.","en":"Only the tests you need, such as blood work, ultrasound, CT or endoscopy, to confirm the diagnosis."}},{"title":{"ar":"مناقشة جميع الخيارات","en":"Discussing every option"},"description":{"ar":"نقارن بلغة واضحة بين الخيارات الجراحية وغير الجراحية والفوائد والمخاطر المتوقعة.","en":"We compare surgical and non-surgical options, expected benefits and risks in plain language."}},{"title":{"ar":"خطتك المخصصة","en":"Your personalised plan"},"description":{"ar":"خطة مكتوبة تشمل التحضير والعملية ومدة الإقامة والتعافي، نتفق عليها معًا.","en":"A written plan covering preparation, the procedure, hospital stay and recovery, agreed together."}}]},"faq":{"eyebrow":{"ar":"أسئلة تفصيلية","en":"Detailed FAQ"},"title":{"ar":"كل ما تريد معرفته عن عمليتك","en":"Everything you want to know about your surgery"}}}'::jsonb),
  ('reviews.blocks', '{"grid":{"eyebrow":{"ar":"شهادات","en":"Testimonials"},"title":{"ar":"ثقة مرضى من مصر والمنطقة العربية","en":"Trusted by patients across Egypt and the region"}}}'::jsonb),
  ('videos.blocks', '{"grid":{"eyebrow":{"ar":"أحدث الفيديوهات","en":"Latest videos"},"title":{"ar":"شاهد وتعلّم واستعد بثقة","en":"Watch, learn and feel prepared"}}}'::jsonb),
  ('articles.blocks', '{"grid":{"eyebrow":{"ar":"أحدث المقالات","en":"Latest articles"},"title":{"ar":"المزيد من المقالات","en":"More to read"}}}'::jsonb)
insert into public.surgeries_services (id, slug, title, summary, description, image_url, sort_order, is_published) values
  ('eb0ae402-2d58-4f7b-a35e-391529c404b0', 'laparoscopic', '{"ar":"جراحات المناظير والجهاز الهضمي","en":"Laparoscopic & GI Surgery"}'::jsonb, '{"ar":"جراحات بالمنظار للمرارة والزائدة الدودية والمعدة والأمعاء.","en":"Keyhole surgery for the gallbladder, appendix, stomach and intestines."}'::jsonb, '{"ar":"تعتمد جراحة المناظير على كاميرا عالية الدقة وأدوات دقيقة تُدخَل عبر فتحات صغيرة. ومقارنةً بالجراحة المفتوحة، تعني ألمًا أقل، وإقامة أقصر في المستشفى، وندوبًا أصغر، وعودة أسرع إلى الحياة الطبيعية.","en":"Laparoscopic (keyhole) surgery uses a high-definition camera and fine instruments inserted through small incisions. Compared with open surgery, it means less pain, a shorter hospital stay, smaller scars and a faster return to normal life."}'::jsonb, '/media/services/laparoscopic.jpg', 0, true),
  ('f4827ee4-927b-4289-af1e-e09326e9a795', 'hernia', '{"ar":"جراحات جدار البطن والفتق","en":"Abdominal Wall & Hernia Surgery"}'::jsonb, '{"ar":"إصلاح متين لجميع أنواع الفتق باستخدام تقنيات الشبكات الحديثة.","en":"Durable repair of all hernia types using modern mesh techniques."}'::jsonb, '{"ar":"الفتق لا يُشفى من تلقاء نفسه ويميل إلى الزيادة مع الوقت. ويوفر الإصلاح الحديث، بالمنظار أو بالجراحة المفتوحة مع شبكة خفيفة، نتائج متينة بنسب ارتداد منخفضة وعودة سريعة إلى النشاط.","en":"A hernia will not heal on its own and tends to enlarge over time. Modern repair, laparoscopic or open with lightweight mesh, offers durable results with low recurrence rates and a quick return to activity."}'::jsonb, '/media/services/hernia.jpg', 1, true),
  ('ba402078-7fb1-478c-abbc-e71a9f35fe11', 'anorectal', '{"ar":"جراحات الشرج والمستقيم","en":"Anorectal Surgery"}'::jsonb, '{"ar":"علاج حديث قليل الألم للبواسير والشرخ والناسور.","en":"Modern, low-pain treatment of hemorrhoids, fissures and fistulas."}'::jsonb, '{"ar":"أمراض الشرج شائعة وقابلة للعلاج بدرجة كبيرة. وباستخدام الليزر والتقنيات الحديثة، تُجرى معظم العمليات في اليوم نفسه بألم أقل بكثير وعودة أسرع إلى العمل مقارنةً بالجراحة التقليدية.","en":"Anorectal conditions are common and highly treatable. Using laser and other modern techniques, most procedures are day cases with markedly less pain and a quicker return to work than traditional surgery."}'::jsonb, '/media/services/anorectal.jpg', 2, true),
  ('97cf3c55-0717-46f0-a540-0ba8933cb8bc', 'endocrine', '{"ar":"جراحات الغدد الصماء","en":"Endocrine Surgery"}'::jsonb, '{"ar":"جراحات الغدة الدرقية والجار درقية والكظرية بدقة تحافظ على الأعصاب.","en":"Thyroid, parathyroid and adrenal surgery with nerve-sparing precision."}'::jsonb, '{"ar":"تتطلب جراحة الغدد الصماء دقة متناهية. وتساعد مراقبة الأعصاب أثناء العملية والحفاظ الدقيق على الغدد الجار درقية في حماية صوتك وتوازن الكالسيوم في جسمك.","en":"Endocrine surgery demands meticulous technique. Intra-operative nerve monitoring and careful preservation of the parathyroid glands help protect your voice and calcium balance."}'::jsonb, '/media/services/endocrine.jpg', 3, true)
insert into public.surgery_procedures (id, service_id, slug, title, description, image_url, sort_order, is_published) values
  ('bcc12b74-d164-4b5c-a6cb-13cb67ab54c6', 'eb0ae402-2d58-4f7b-a35e-391529c404b0', 'cholecystectomy', '{"ar":"استئصال المرارة بالمنظار","en":"Laparoscopic cholecystectomy"}'::jsonb, '{"ar":"استئصال المرارة في حالات الحصوات المسببة للأعراض أو التهاب المرارة أو الزوائد اللحمية، وتستغرق العملية عادةً من 45 إلى 60 دقيقة مع الخروج خلال 24 ساعة.","en":"Removal of the gallbladder for symptomatic gallstones, cholecystitis or polyps. Usually a 45–60 minute procedure with discharge within 24 hours."}'::jsonb, '/media/procedures/cholecystectomy.jpg', 0, true),
  ('f1c0d512-fbd5-461a-a4c8-0a4f15216ebe', 'eb0ae402-2d58-4f7b-a35e-391529c404b0', 'appendectomy', '{"ar":"استئصال الزائدة الدودية بالمنظار","en":"Laparoscopic appendectomy"}'::jsonb, '{"ar":"استئصال سريع وآمن للزائدة الملتهبة عبر ثلاث فتحات صغيرة، مما يقلل خطر التهاب الجرح ومدة التعافي.","en":"Rapid, safe removal of an inflamed appendix through three small incisions, reducing wound infection and recovery time."}'::jsonb, '/media/procedures/appendectomy.jpg', 1, true),
  ('123fd1a4-7074-4ee8-a760-01ef09379176', 'eb0ae402-2d58-4f7b-a35e-391529c404b0', 'anti-reflux', '{"ar":"جراحة الارتجاع وإصلاح فتق الحجاب الحاجز","en":"Anti-reflux surgery & hiatal hernia repair"}'::jsonb, '{"ar":"عملية تثنية قاع المعدة بالمنظار لإصلاح فتق الحجاب الحاجز وعلاج الارتجاع المزمن عندما لا تكفي الأدوية.","en":"Laparoscopic fundoplication to repair a hiatal hernia and control chronic reflux when medication is no longer enough."}'::jsonb, '/media/procedures/anti-reflux.jpg', 2, true),
  ('8a63c7e6-c3d0-4deb-a5fc-e40483af89f0', 'eb0ae402-2d58-4f7b-a35e-391529c404b0', 'diagnostic-laparoscopy', '{"ar":"المنظار التشخيصي","en":"Diagnostic laparoscopy"}'::jsonb, '{"ar":"فحص داخل البطن بأقل تدخل جراحي لتشخيص الآلام غير المبررة، مع إمكانية العلاج في الجلسة نفسها عند الحاجة.","en":"A minimally invasive look inside the abdomen to diagnose unexplained pain, with treatment in the same session when needed."}'::jsonb, '/media/procedures/diagnostic-laparoscopy.jpg', 3, true),
  ('b615c925-a37e-4be6-ab90-bcee00cf3c7c', 'f4827ee4-927b-4289-af1e-e09326e9a795', 'inguinal-hernia', '{"ar":"إصلاح الفتق الإربي بالمنظار (TAPP / TEP)","en":"Inguinal hernia repair (TAPP / TEP)"}'::jsonb, '{"ar":"إصلاح فتق المنطقة الإربية بالمنظار، بما في ذلك الحالات المزدوجة والمرتجعة، مع ألم أقل بعد العملية.","en":"Laparoscopic repair of groin hernias, including bilateral and recurrent cases, with less post-operative pain."}'::jsonb, '/media/procedures/inguinal-hernia.jpg', 0, true),
  ('430ddcc9-b8e9-45f3-a77a-a37e677eea8d', 'f4827ee4-927b-4289-af1e-e09326e9a795', 'umbilical-hernia', '{"ar":"إصلاح الفتق السُّري وحول السُّرة","en":"Umbilical & paraumbilical hernia repair"}'::jsonb, '{"ar":"إصلاح الفتق حول السُّرة مع اهتمام خاص بالنتيجة التجميلية.","en":"Repair of hernias around the navel with careful attention to the cosmetic result."}'::jsonb, '/media/procedures/umbilical-hernia.jpg', 1, true),
  ('5dcb2298-699f-4bef-a82e-ab0017bd3cfa', 'f4827ee4-927b-4289-af1e-e09326e9a795', 'incisional-hernia', '{"ar":"إصلاح الفتق الجراحي","en":"Incisional hernia repair"}'::jsonb, '{"ar":"إصلاح الفتق الذي يظهر في مكان جرح عملية سابقة باستخدام الشبكة بالمنظار أو بالجراحة المفتوحة.","en":"Repair of hernias that develop through previous surgical scars, using laparoscopic or open mesh techniques."}'::jsonb, '/media/procedures/incisional-hernia.jpg', 2, true),
  ('71c95f26-081a-4f1f-aae7-f1f6af408756', 'f4827ee4-927b-4289-af1e-e09326e9a795', 'diastasis-recti', '{"ar":"علاج انفصال عضلات البطن وإعادة بناء جدار البطن","en":"Diastasis recti & abdominal wall reconstruction"}'::jsonb, '{"ar":"استعادة قوة جدار البطن وشكله بعد الحمل أو العمليات السابقة.","en":"Restoring the strength and shape of the abdominal wall after pregnancy or previous surgery."}'::jsonb, '/media/procedures/diastasis-recti.jpg', 3, true),
  ('bbdeefd4-b710-4f95-a20c-e2d227cebfe9', 'ba402078-7fb1-478c-abbc-e71a9f35fe11', 'hemorrhoids-laser', '{"ar":"علاج البواسير بالليزر","en":"Laser hemorrhoidoplasty"}'::jsonb, '{"ar":"تقليص البواسير من الداخل باستخدام طاقة الليزر: ألم محدود، ودون جروح مفتوحة، وتعافٍ سريع.","en":"Shrinks hemorrhoids from within using laser energy: minimal pain, no open wounds and a fast recovery."}'::jsonb, '/media/procedures/hemorrhoids-laser.jpg', 0, true),
  ('9929a605-3159-489b-a6a5-e2db9b25dccb', 'ba402078-7fb1-478c-abbc-e71a9f35fe11', 'anal-fissure', '{"ar":"علاج الشرخ الشرجي","en":"Anal fissure treatment"}'::jsonb, '{"ar":"بدءًا من العلاج الدوائي وحقن البوتوكس، وصولًا إلى قطع العضلة العاصرة الداخلية الجانبي في الحالات المزمنة.","en":"From medical therapy and botulinum toxin to lateral internal sphincterotomy for chronic fissures."}'::jsonb, '/media/procedures/anal-fissure.jpg', 1, true),
  ('36fcae4f-3900-41ef-a025-f567901374e5', 'ba402078-7fb1-478c-abbc-e71a9f35fe11', 'anal-fistula', '{"ar":"جراحة الناسور الشرجي","en":"Anal fistula surgery"}'::jsonb, '{"ar":"تقنيات تحافظ على العضلة العاصرة، منها الليزر (FiLaC) وخيط السيتون، لحماية القدرة على التحكم.","en":"Sphincter-preserving techniques, including laser (FiLaC) and seton placement, to protect continence."}'::jsonb, '/media/procedures/anal-fistula.jpg', 2, true),
  ('d23402a3-d453-4bba-ac3c-149397f357a3', 'ba402078-7fb1-478c-abbc-e71a9f35fe11', 'pilonidal-sinus', '{"ar":"علاج الناسور العصعصي (الشعرة)","en":"Pilonidal sinus treatment"}'::jsonb, '{"ar":"تقنيات بأقل تدخل جراحي وتقنيات الشريحة الجلدية لتقليل الارتداد وتسريع الالتئام.","en":"Minimally invasive and flap techniques that reduce recurrence and shorten healing time."}'::jsonb, '/media/procedures/pilonidal-sinus.jpg', 3, true),
  ('f9445c58-5f44-488e-acfe-66a2d9a12fbd', '97cf3c55-0717-46f0-a540-0ba8933cb8bc', 'total-thyroidectomy', '{"ar":"الاستئصال الكلي للغدة الدرقية","en":"Total thyroidectomy"}'::jsonb, '{"ar":"استئصال الغدة الدرقية بالكامل في حالات التضخم متعدد العُقيدات أو مرض جريفز أو الأورام المؤكدة.","en":"Complete removal of the thyroid for multinodular goitre, Graves’ disease or confirmed cancer."}'::jsonb, '/media/procedures/total-thyroidectomy.jpg', 0, true),
  ('5df5fa32-f6a8-481e-a0d8-16600e7eb982', '97cf3c55-0717-46f0-a540-0ba8933cb8bc', 'hemithyroidectomy', '{"ar":"استئصال فص من الغدة الدرقية","en":"Hemithyroidectomy (lobectomy)"}'::jsonb, '{"ar":"استئصال أحد فصي الغدة في حالة وجود عُقيدة واحدة مشتبه بها أو متزايدة الحجم، مع الحفاظ غالبًا على وظيفة الغدة الطبيعية.","en":"Removal of one thyroid lobe for a single suspicious or enlarging nodule, often preserving natural thyroid function."}'::jsonb, '/media/procedures/hemithyroidectomy.jpg', 1, true),
  ('36d9217a-5510-48cf-aca8-20f31f8b0a1c', '97cf3c55-0717-46f0-a540-0ba8933cb8bc', 'parathyroidectomy', '{"ar":"استئصال الغدة الجار درقية","en":"Parathyroidectomy"}'::jsonb, '{"ar":"استئصال موجّه للغدة الجار درقية مفرطة النشاط لتصحيح ارتفاع الكالسيوم وحماية العظام والكلى.","en":"Targeted removal of an overactive parathyroid gland to correct high calcium levels and protect bones and kidneys."}'::jsonb, '/media/procedures/parathyroidectomy.jpg', 2, true),
  ('570830be-7305-482d-a4f9-784e7989b19a', '97cf3c55-0717-46f0-a540-0ba8933cb8bc', 'adrenalectomy', '{"ar":"استئصال الغدة الكظرية بالمنظار","en":"Laparoscopic adrenalectomy"}'::jsonb, '{"ar":"استئصال أورام الغدة الكظرية بالمنظار بألم أقل وتعافٍ أسرع من الجراحة المفتوحة.","en":"Keyhole removal of adrenal tumours with less pain and a faster recovery than open surgery."}'::jsonb, '/media/procedures/adrenalectomy.jpg', 3, true)
insert into public.articles (id, slug, category, title, excerpt, content, cover_url, is_featured, status, published_at, read_minutes, seo) values
  ('08d42e23-0833-4d52-a04f-a0d74db5e2a5', 'laparoscopic-gallbladder-removal-guide', '{"ar":"جراحة المناظير","en":"Laparoscopic surgery"}'::jsonb, '{"ar":"استئصال المرارة بالمنظار: دليل شامل للمريض","en":"Laparoscopic Gallbladder Removal: A Complete Patient Guide"}'::jsonb, '{"ar":"كل ما تحتاج معرفته عن حصوات المرارة، ومتى يُنصح بالجراحة، وماذا يحدث يوم العملية، ومتى يمكنك أن تتوقع التعافي.","en":"Everything you need to know about gallstones, when surgery is recommended, what happens on the day and how quickly you can expect to recover."}'::jsonb, '{"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"تُعد حصوات المرارة من أكثر مشكلات الجهاز الهضمي شيوعًا. لا تظهر الأعراض لدى كثيرين، لكن عندما تسبب الحصوات ألمًا أو التهابًا أو مضاعفات، يصبح استئصال المرارة بالمنظار العلاج الجذري والأكثر أمانًا."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"متى يُنصح بالجراحة؟"}]},{"type":"paragraph","content":[{"type":"text","text":"يُنصح بالجراحة عادةً عند تكرار نوبات الألم في الجزء العلوي الأيمن من البطن (المغص المراري)، أو التهاب المرارة، أو التهاب البنكرياس الناتج عن الحصوات، أو انتقال الحصوات إلى القناة المرارية. أما الحصوات الصامتة المكتشفة بالصدفة فغالبًا ما تكفي متابعتها."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"ماذا يحدث أثناء العملية؟"}]},{"type":"paragraph","content":[{"type":"text","text":"تحت التخدير الكلي، تُعمل أربع فتحات صغيرة يتراوح طولها بين 5 و10 ملم، وتوجّه كاميرا عالية الدقة الجرّاح لفصل المرارة واستئصالها بأمان. وتستغرق العملية عادةً من 45 إلى 60 دقيقة."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"التعافي والحياة بعد استئصال المرارة"}]},{"type":"paragraph","content":[{"type":"text","text":"يمشي معظم المرضى بعد ساعات من العملية، ويغادرون المستشفى خلال 24 ساعة، ويعودون إلى الأعمال المكتبية خلال أسبوع."}]},{"type":"paragraph","content":[{"type":"text","text":"يستمر الكبد في إفراز العصارة الصفراوية، لذا يتكيف الهضم سريعًا، وقد يُفضّل البعض فقط الاعتدال في الوجبات الدسمة خلال الأسابيع الأولى."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gallstones are one of the most common digestive problems. Many people never develop symptoms, but when stones cause pain, inflammation or complications, removing the gallbladder laparoscopically is the definitive and safest treatment."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When is surgery recommended?"}]},{"type":"paragraph","content":[{"type":"text","text":"Surgery is usually advised if you have recurrent episodes of upper-right abdominal pain (biliary colic), an inflamed gallbladder (cholecystitis), gallstone pancreatitis or stones that have passed into the bile duct. Silent stones discovered incidentally often only need monitoring."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens during the operation?"}]},{"type":"paragraph","content":[{"type":"text","text":"Under general anaesthesia, four small incisions of 5–10 mm are made. A high-definition camera guides the surgeon to separate and remove the gallbladder safely. The operation typically takes 45–60 minutes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Recovery and life without a gallbladder"}]},{"type":"paragraph","content":[{"type":"text","text":"Most patients walk within hours, go home within 24 hours and return to office work within a week."}]},{"type":"paragraph","content":[{"type":"text","text":"The liver continues to produce bile, so digestion adapts quickly. Some people simply find that very fatty meals are best enjoyed in moderation during the first few weeks."}]}]}}'::jsonb, '/media/articles/article-1.jpg', true, 'published', '2026-09-28T08:00:00+00:00', 6, '{}'::jsonb),
  ('1f2883b6-c857-4a15-a702-b9ac3d4b1909', 'inguinal-hernia-when-to-operate', '{"ar":"جراحة الفتق","en":"Hernia surgery"}'::jsonb, '{"ar":"الفتق الإربي: الأعراض والمخاطر ومتى تجب الجراحة","en":"Inguinal Hernia: Symptoms, Risks and When to Have Surgery"}'::jsonb, '{"ar":"التورم في المنطقة الإربية ليس مشكلة شكلية فحسب. تعرّف على كيفية حدوث الفتق، والأعراض التي تستدعي رعاية عاجلة، ولماذا يكون الإصلاح المبكر هو الخيار الأحكم غالبًا.","en":"A bulge in the groin is more than a cosmetic issue. Learn how hernias develop, which symptoms need urgent care and why early repair is often wiser."}'::jsonb, '{"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"يحدث الفتق الإربي عندما يندفع جزء من الأمعاء أو الأنسجة الدهنية عبر نقطة ضعف في أسفل جدار البطن، فيظهر تورم في المنطقة الإربية. وهو أكثر شيوعًا لدى الرجال، ويمكن أن يظهر في أي عمر."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"الأعراض الشائعة"}]},{"type":"paragraph","content":[{"type":"text","text":"تورم يزداد مع السعال أو الإجهاد أو الوقوف ويختفي عند الاستلقاء، مع شعور بالثقل أو الألم في المنطقة الإربية، خاصة في نهاية اليوم."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"متى تكون الحالة طارئة؟"}]},{"type":"paragraph","content":[{"type":"text","text":"توجّه إلى الطوارئ فورًا إذا أصبح التورم صلبًا ومؤلمًا ولا يمكن إرجاعه، أو صاحبه قيء أو عدم القدرة على إخراج الغازات، فقد تكون هذه علامات اختناق الفتق التي تتطلب جراحة فورية."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"لماذا الإصلاح بالمنظار؟"}]},{"type":"paragraph","content":[{"type":"text","text":"يعتمد الإصلاح بالمنظار (TAPP أو TEP) على وضع شبكة خلف جدار البطن من خلال فتحات صغيرة، ويتيح إصلاح الجانبين في جلسة واحدة، مع ألم أقل وعودة أسرع إلى النشاط."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An inguinal hernia occurs when part of the intestine or fatty tissue pushes through a weak spot in the lower abdominal wall, creating a bulge in the groin. It is far more common in men and can appear at any age."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Common symptoms"}]},{"type":"paragraph","content":[{"type":"text","text":"A swelling that increases with coughing, straining or standing and disappears when lying down, together with a dragging or aching sensation in the groin, especially by the end of the day."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When is it an emergency?"}]},{"type":"paragraph","content":[{"type":"text","text":"Seek urgent care if the bulge becomes firm and painful and cannot be pushed back, or if it is accompanied by vomiting or an inability to pass gas. These may be signs of a strangulated hernia, which requires immediate surgery."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why choose laparoscopic repair?"}]},{"type":"paragraph","content":[{"type":"text","text":"Laparoscopic repair (TAPP or TEP) places a mesh behind the abdominal wall through small incisions. It allows both sides to be repaired in one session and is associated with less pain and a faster return to activity."}]}]}}'::jsonb, '/media/articles/article-2.jpg', false, 'published', '2026-09-14T08:00:00+00:00', 5, '{}'::jsonb),
  ('baf13901-de06-40f9-a039-b8b0fbb5f4ee', 'hemorrhoids-modern-treatment', '{"ar":"جراحات الشرج","en":"Anorectal surgery"}'::jsonb, '{"ar":"البواسير: خيارات علاج حديثة تتجاوز الجراحة التقليدية","en":"Hemorrhoids: Modern Treatment Options Beyond Traditional Surgery"}'::jsonb, '{"ar":"البواسير شائعة وقابلة للعلاج بدرجة كبيرة. تعرّف على الخيارات المتاحة اليوم، بدءًا من تغيير نمط الحياة وصولًا إلى العلاج بالليزر قليل الألم.","en":"Hemorrhoids are common and very treatable. Discover the options available today, from lifestyle changes to low-pain laser procedures."}'::jsonb, '{"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"البواسير أوعية دموية متورمة في القناة الشرجية قد تسبب نزيفًا أو حكة أو انزعاجًا أو بروزًا. وكثيرًا ما يؤخر الحرجُ العلاجَ، رغم أن معظم الحالات يمكن علاجها ببساطة وفعالية."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"البداية بالأساسيات"}]},{"type":"paragraph","content":[{"type":"text","text":"تساعد زيادة الألياف في الطعام وشرب كميات كافية من الماء وتجنب الحزق أو الجلوس الطويل في المرحاض على علاج كثير من الحالات المبكرة، كما تخفف العلاجات الموضعية الأعراض أثناء النوبات."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"إجراءات في العيادة"}]},{"type":"paragraph","content":[{"type":"text","text":"في حالات البواسير الداخلية المستمرة، يُعد ربط البواسير بالحلقات المطاطية إجراءً سريعًا في العيادة يقطع التروية الدموية عنها فتنكمش وتسقط خلال أيام."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"علاج البواسير بالليزر"}]},{"type":"paragraph","content":[{"type":"text","text":"يمكن علاج البواسير المتقدمة أو المرتجعة بطاقة الليزر من الداخل، دون جروح مفتوحة وبألم محدود، ويعود معظم المرضى إلى عملهم خلال أيام قليلة."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hemorrhoids are swollen blood vessels in the anal canal that can cause bleeding, itching, discomfort or prolapse. Embarrassment often delays treatment, yet most cases can be managed simply and effectively."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start with the basics"}]},{"type":"paragraph","content":[{"type":"text","text":"Increasing dietary fibre, drinking enough water and avoiding prolonged straining or sitting on the toilet resolve many early cases. Topical treatments can relieve symptoms during flare-ups."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Clinic procedures"}]},{"type":"paragraph","content":[{"type":"text","text":"For persistent internal hemorrhoids, rubber band ligation is a quick clinic procedure that cuts off the blood supply to the hemorrhoid so that it shrinks and falls off within days."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Laser hemorrhoidoplasty"}]},{"type":"paragraph","content":[{"type":"text","text":"Advanced or recurrent hemorrhoids can be treated with laser energy delivered from within. There are no open wounds, pain is minimal and most patients return to work within a few days."}]}]}}'::jsonb, '/media/articles/article-3.jpg', false, 'published', '2026-08-31T08:00:00+00:00', 5, '{}'::jsonb),
  ('9f081813-54c7-4735-a943-e83b6325269a', 'thyroid-nodules-explained', '{"ar":"جراحة الغدد الصماء","en":"Endocrine surgery"}'::jsonb, '{"ar":"عُقيدات الغدة الدرقية: افهم تشخيصك","en":"Thyroid Nodules: Understanding Your Diagnosis"}'::jsonb, '{"ar":"معظم عُقيدات الغدة الدرقية حميدة. إليك كيف يقيّمها الأطباء، والحالات المحددة التي تصبح فيها الجراحة الخيار الصحيح.","en":"Most thyroid nodules are benign. Here is how doctors evaluate them and the specific situations in which surgery becomes the right choice."}'::jsonb, '{"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"عُقيدات الغدة الدرقية كتل داخل الغدة، وهي شائعة جدًا وغالبًا ما تُكتشف في فحص السونار الروتيني، وأكثر من 90% منها حميدة. والأهم هو التقييم الدقيق والمنهجي."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"كيف تُقيَّم العُقيدات؟"}]},{"type":"paragraph","content":[{"type":"text","text":"يجمع التقييم بين تحاليل وظائف الغدة، وفحص بالسونار عالي الدقة يصنّف خصائص العُقيدة، وعند الحاجة، أخذ عينة بالإبرة الدقيقة (FNA)."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"متى يُنصح بالجراحة؟"}]},{"type":"paragraph","content":[{"type":"text","text":"تُدرس الجراحة في حالة العُقيدات المشتبه بها أو الخبيثة في نتيجة العينة، أو العُقيدات الكبيرة التي تسبب ضغطًا مثل صعوبة البلع أو التنفس، أو العُقيدات مفرطة النشاط، أو لأسباب تجميلية."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"ماذا تتضمن الجراحة؟"}]},{"type":"paragraph","content":[{"type":"text","text":"بحسب النتائج، يُستأصل فص واحد من الغدة أو الغدة بالكامل عبر شق صغير في ثنية طبيعية بالرقبة، مع مراقبة الأعصاب لحماية الصوت."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thyroid nodules are lumps within the thyroid gland. They are extremely common, often found on a routine ultrasound, and more than 90% are benign. The key is a careful, structured evaluation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How nodules are evaluated"}]},{"type":"paragraph","content":[{"type":"text","text":"Assessment combines thyroid function tests, a high-resolution ultrasound that grades the nodule’s features and, when indicated, a fine-needle aspiration (FNA) biopsy."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When is surgery recommended?"}]},{"type":"paragraph","content":[{"type":"text","text":"Surgery is considered for nodules that are suspicious or malignant on biopsy, large nodules causing pressure symptoms such as difficulty swallowing or breathing, overactive (toxic) nodules, or for cosmetic concerns."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What surgery involves"}]},{"type":"paragraph","content":[{"type":"text","text":"Depending on the findings, one lobe (hemithyroidectomy) or the entire gland (total thyroidectomy) is removed through a small incision placed in a natural skin crease of the neck, with nerve monitoring to protect the voice."}]}]}}'::jsonb, '/media/articles/article-4.jpg', false, 'published', '2026-08-17T08:00:00+00:00', 5, '{}'::jsonb),
  ('aa769165-d9da-437d-acf4-60d4403abee2', 'preparing-for-surgery-checklist', '{"ar":"دليل المريض","en":"Patient guide"}'::jsonb, '{"ar":"الاستعداد للجراحة: قائمة تحقق عملية","en":"Preparing for Surgery: A Practical Checklist"}'::jsonb, '{"ar":"الاستعداد الجيد يعني عملية أكثر سلاسة وتعافيًا أسرع. استخدم هذه القائمة في الأيام والساعات التي تسبق عمليتك.","en":"Good preparation means a smoother operation and a faster recovery. Use this checklist in the days and hours before your procedure."}'::jsonb, '{"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"الشعور بالاستعداد يقلل القلق ويساعد جسمك على التعافي. تنطبق هذه الخطوات العملية على معظم عمليات الجراحة العامة المخطط لها، وسيزودك الفريق الجراحي بتعليمات خاصة بحالتك."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"قبل العملية بأسبوع إلى أسبوعين"}]},{"type":"paragraph","content":[{"type":"text","text":"أجرِ التحاليل والأشعة المطلوبة، وراجع أدويتك المعتادة مع الطبيب، خاصة مسيلات الدم وأدوية السكري، وتوقف عن التدخين لتقليل خطر المضاعفات."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"في اليوم السابق"}]},{"type":"paragraph","content":[{"type":"text","text":"جهّز ملابس واسعة ومريحة، ورتّب لوجود مرافق يعود معك إلى المنزل، والتزم بتعليمات الصيام بدقة، وعادةً ما يكون ذلك بالامتناع عن الطعام لست ساعات قبل العملية."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"في يوم العملية"}]},{"type":"paragraph","content":[{"type":"text","text":"استحم، وانزع المجوهرات وطلاء الأظافر، وأحضر تقاريرك وبطاقة الهوية، وأخبر الفريق بأي أعراض جديدة مثل الحرارة أو السعال."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Feeling prepared reduces anxiety and helps your body recover. These practical steps apply to most planned general surgery procedures; your surgical team will give you instructions specific to your case."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"One to two weeks before"}]},{"type":"paragraph","content":[{"type":"text","text":"Complete the requested blood tests and scans, review your regular medications with the doctor (especially blood thinners and diabetes medication) and stop smoking to lower the risk of complications."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The day before"}]},{"type":"paragraph","content":[{"type":"text","text":"Prepare loose, comfortable clothing, arrange for someone to accompany you home and follow the fasting instructions carefully, usually no food for six hours before surgery."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"On the day of surgery"}]},{"type":"paragraph","content":[{"type":"text","text":"Shower, remove jewellery and nail polish, bring your reports and ID, and tell the team about any new symptoms such as a fever or a cough."}]}]}}'::jsonb, '/media/articles/article-5.jpg', false, 'published', '2026-08-03T08:00:00+00:00', 4, '{}'::jsonb),
  ('5df57106-cad7-42bc-a3c9-6e0fe9a2ec91', 'appendicitis-warning-signs', '{"ar":"جراحة الطوارئ","en":"Emergency surgery"}'::jsonb, '{"ar":"التهاب الزائدة الدودية: علامات تحذيرية لا تتجاهلها","en":"Appendicitis: Warning Signs You Shouldn’t Ignore"}'::jsonb, '{"ar":"قد يتطور التهاب الزائدة بسرعة، والتعرّف على الأعراض المبكرة وطلب المساعدة سريعًا يمكن أن يمنع مضاعفات خطيرة.","en":"Appendicitis can progress quickly. Recognising the early symptoms and seeking help promptly can prevent serious complications."}'::jsonb, '{"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"التهاب الزائدة الدودية من أكثر الطوارئ الجراحية شيوعًا، ويمكن أن يصيب أي شخص، لكنه أكثر حدوثًا بين سن العاشرة والثلاثين."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"الأعراض المعتادة"}]},{"type":"paragraph","content":[{"type":"text","text":"ألم يبدأ حول السُّرة ثم ينتقل إلى أسفل يمين البطن خلال عدة ساعات، مع فقدان الشهية والغثيان أو القيء وارتفاع طفيف في الحرارة، وغالبًا ما يزداد الألم مع المشي أو السعال."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"لماذا التوقيت مهم؟"}]},{"type":"paragraph","content":[{"type":"text","text":"إذا تأخر العلاج، فقد تنفجر الزائدة الملتهبة وتسبب التهابًا في الغشاء البريتوني أو خُرّاجًا، مما يطيل مدة الإقامة في المستشفى. وتجنّب المسكنات والملينات قبل الفحص لأنها قد تخفي الأعراض."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"العلاج"}]},{"type":"paragraph","content":[{"type":"text","text":"يُعد استئصال الزائدة بالمنظار العلاج القياسي، ويغادر معظم المرضى المستشفى خلال 24 إلى 48 ساعة، ويعودون إلى أنشطتهم الطبيعية خلال أسبوع إلى أسبوعين."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Appendicitis is inflammation of the appendix and one of the most common surgical emergencies. It can affect anyone, but it is most frequent between the ages of 10 and 30."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Classic symptoms"}]},{"type":"paragraph","content":[{"type":"text","text":"Pain that starts around the navel and moves to the lower right abdomen over several hours, loss of appetite, nausea or vomiting, and a low-grade fever. The pain often worsens with walking or coughing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why timing matters"}]},{"type":"paragraph","content":[{"type":"text","text":"If treatment is delayed, the inflamed appendix can perforate and cause peritonitis or an abscess, leading to a longer hospital stay. Avoid painkillers and laxatives until you have been assessed, as they may mask symptoms."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Treatment"}]},{"type":"paragraph","content":[{"type":"text","text":"Laparoscopic appendectomy is the standard treatment. Most patients go home within 24–48 hours and return to normal activities within one to two weeks."}]}]}}'::jsonb, '/media/articles/article-6.jpg', false, 'published', '2026-07-20T08:00:00+00:00', 4, '{}'::jsonb),
  ('2f8e8738-0294-4b45-a564-7f3b8f8846ea', 'recovery-after-abdominal-surgery', '{"ar":"التعافي","en":"Recovery"}'::jsonb, '{"ar":"التعافي بعد جراحات البطن: نصائح للتغذية والنشاط","en":"Recovery After Abdominal Surgery: Nutrition and Activity Tips"}'::jsonb, '{"ar":"ما تأكله وطريقة حركتك بعد الجراحة يؤثران مباشرة في الالتئام. اتبع هذه النصائح العملية لتعافٍ أكثر سلاسة وسرعة.","en":"What you eat and how you move after surgery directly affect healing. Follow these practical tips for a smoother, faster recovery."}'::jsonb, '{"ar":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"لا ينتهي التعافي بمغادرة المستشفى؛ فالخيارات التي تتخذها في الأسابيع التالية، مثل ما تأكله وكيف تتحرك وكيف تعتني بجروحك، تُحدث فرقًا حقيقيًا في سرعة شفائك."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"تغذَّ لتتعافى"}]},{"type":"paragraph","content":[{"type":"text","text":"ابدأ بوجبات خفيفة وزِد الكمية تدريجيًا، وركّز على البروتين (البيض والسمك والدجاج والبقوليات) والفواكه والخضروات للحصول على الفيتامينات، مع الإكثار من السوائل. وتساعد الألياف على تجنب الإمساك، خاصة أثناء تناول المسكنات."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"تحرّك مبكرًا… ولكن بحكمة"}]},{"type":"paragraph","content":[{"type":"text","text":"يحسّن المشي القصير المتكرر منذ اليوم الأول الدورة الدموية ويقلل خطر الجلطات والتهابات الصدر. وتجنّب حمل ما يزيد على 5 كجم لمدة أربعة أسابيع تقريبًا، أو حسب التعليمات."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"متى تتصل بالجرّاح؟"}]},{"type":"paragraph","content":[{"type":"text","text":"تواصل معنا إذا ظهرت حرارة، أو زاد احمرار الجرح أو خرجت منه إفرازات، أو اشتد ألم البطن، أو استمر القيء، أو شعرت بضيق في التنفس."}]}]},"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recovery does not end when you leave the hospital. The choices you make in the following weeks, such as what you eat, how you move and how you care for your wounds, make a real difference to how quickly you heal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Eat to heal"}]},{"type":"paragraph","content":[{"type":"text","text":"Start with light meals and increase gradually. Prioritise protein (eggs, fish, chicken, legumes), fruit and vegetables for vitamins, and plenty of fluids. Fibre helps prevent constipation, especially while you are taking pain medication."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Move early, but wisely"}]},{"type":"paragraph","content":[{"type":"text","text":"Short, frequent walks from the first day improve circulation and reduce the risk of clots and chest infections. Avoid lifting anything heavier than 5 kg for about four weeks, or as advised."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When to call your surgeon"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact us if you develop a fever, increasing redness or discharge from a wound, worsening abdominal pain, persistent vomiting or shortness of breath."}]}]}}'::jsonb, '/media/articles/article-7.jpg', false, 'published', '2026-07-06T08:00:00+00:00', 5, '{}'::jsonb)
