insert into public.patient_reviews (id, patient_name, procedure, review_text, rating, is_visible, show_on_home, sort_order) values
  ('79d7d4db-5ec1-4efc-a513-c9a5cd30951c', '{"ar":"محمد ع.","en":"Mohamed A."}'::jsonb, '{"ar":"استئصال المرارة بالمنظار","en":"Laparoscopic gallbladder removal"}'::jsonb, '{"ar":"عانيت من نوبات حصوات المرارة لمدة عامين. شرح لي د. أحمد كل شيء بوضوح، ومرّت العملية بسلاسة، وعدت إلى المنزل صباح اليوم التالي، ثم إلى عملي خلال أسبوع.","en":"I had suffered from gallstone attacks for two years. Dr. Ahmed explained everything clearly, the operation went smoothly and I was home the next morning. I was back at work within a week."}'::jsonb, 5, true, true, 0),
  ('a4b4d60a-d545-405e-afdb-2ae58be8e149', '{"ar":"سارة م.","en":"Sara M."}'::jsonb, '{"ar":"علاج البواسير بالليزر","en":"Laser hemorrhoid treatment"}'::jsonb, '{"ar":"أجّلت العلاج لسنوات خوفًا من الألم، لكن العلاج بالليزر كان أسهل بكثير مما تخيلت، والمتابعة عبر واتساب منحتني شعورًا بالأمان طوال الوقت.","en":"I delayed treatment for years out of fear of pain. The laser procedure was far easier than I imagined, and the follow-up on WhatsApp made me feel safe the whole time."}'::jsonb, 5, true, true, 1),
  ('1244c542-9986-4443-a074-86942904ee0f', '{"ar":"خالد ي.","en":"Khaled Y."}'::jsonb, '{"ar":"إصلاح فتق إربي مزدوج","en":"Bilateral inguinal hernia repair"}'::jsonb, '{"ar":"تم إصلاح الفتقين بالمنظار في عملية واحدة. ألم بسيط، وندوب صغيرة جدًا، ورعاية ممتازة من الفريق بأكمله.","en":"Both hernias were repaired laparoscopically in one operation. Minimal pain, tiny scars and excellent care from the whole team."}'::jsonb, 5, true, true, 2),
  ('2acad27d-99b0-4701-a0c8-b0339403f13a', '{"ar":"منى س.","en":"Mona S."}'::jsonb, '{"ar":"استئصال كلي للغدة الدرقية","en":"Total thyroidectomy"}'::jsonb, '{"ar":"كنت قلقة على صوتي لأنني معلمة، لكن د. أحمد طمأنني وشرح لي تقنية مراقبة الأعصاب. صوتي طبيعي تمامًا والندبة بالكاد تُرى.","en":"As a teacher, I was worried about my voice. Dr. Ahmed reassured me and explained the nerve-monitoring technique. My voice is perfectly normal and my scar is barely visible."}'::jsonb, 5, true, true, 3),
  ('74c1757d-5d7e-4ec5-a7dd-26f64de230e7', '{"ar":"أحمد ر.","en":"Ahmed R."}'::jsonb, '{"ar":"استئصال الزائدة بالمنظار (طوارئ)","en":"Emergency laparoscopic appendectomy"}'::jsonb, '{"ar":"وصلت إلى الطوارئ في منتصف الليل، وخلال ساعات تأكد التشخيص وأُجريت العملية. احترافية وسرعة وتعامل إنساني راقٍ.","en":"I arrived at the emergency room at midnight. Within hours the diagnosis was confirmed and the surgery was done. Professional, fast and very humane."}'::jsonb, 5, true, true, 4),
  ('797f5320-4fcf-4e0a-aaba-79db141efdd4', '{"ar":"ريم ح.","en":"Reem H."}'::jsonb, '{"ar":"إصلاح فتق سُري وانفصال عضلات البطن","en":"Umbilical hernia & diastasis repair"}'::jsonb, '{"ar":"بعد ولادتين عانيت من فتق سُري وانفصال في عضلات البطن، وجاءت النتيجة فوق توقعاتي طبيًا وجماليًا.","en":"After two pregnancies I had both an umbilical hernia and separated abdominal muscles. The result exceeded my expectations, both medically and cosmetically."}'::jsonb, 5, true, true, 5),
  ('fd28bed1-a470-47fa-afc5-a9a02eedc2d0', '{"ar":"يوسف ك.","en":"Youssef K."}'::jsonb, '{"ar":"علاج الناسور العصعصي","en":"Pilonidal sinus surgery"}'::jsonb, '{"ar":"خضعت لعمليتين لم تنجحا في مكان آخر، فاستخدم د. أحمد تقنية مختلفة، ومرّ عام كامل دون أي ارتداد. أنصح به بشدة.","en":"I had two unsuccessful operations elsewhere. Dr. Ahmed used a different technique, and a year later there has been no recurrence. Highly recommended."}'::jsonb, 5, true, true, 6),
  ('b4fd7731-fc2f-4d7d-a26b-757ac781b0c2', '{"ar":"هالة ن.","en":"Hala N."}'::jsonb, '{"ar":"علاج الشرخ الشرجي","en":"Anal fissure treatment"}'::jsonb, '{"ar":"بدأ بالعلاج الدوائي أولًا، ولم يوصِ بالجراحة إلا عندما أصبحت ضرورية فعلًا. أقدّر صدقه كثيرًا، وكانت النتيجة ممتازة.","en":"He tried medical treatment first and only recommended surgery when it was truly needed. I really appreciated his honesty, and the result was excellent."}'::jsonb, 5, true, true, 7),
  ('f01d152a-2f8b-463d-ad0d-6d250eb774fc', '{"ar":"عمر ف.","en":"Omar F."}'::jsonb, '{"ar":"جراحة الارتجاع المريئي","en":"Anti-reflux surgery"}'::jsonb, '{"ar":"أصبحت سنوات الحموضة والأدوية اليومية من الماضي. أُجريت العملية بالمنظار، وعدت إلى تناول الطعام بشكل طبيعي خلال أسبوعين.","en":"Years of heartburn and daily medication are behind me. The surgery was laparoscopic and I was eating normally within two weeks."}'::jsonb, 5, true, true, 8)
insert into public.faqs (id, page, question, answer, is_visible, sort_order) values
  ('6cea2567-87b9-4af7-a08f-0edcaa2d3779', 'home', '{"ar":"كيف أحجز موعدًا؟","en":"How do I book an appointment?"}'::jsonb, '{"ar":"يمكنك الحجز من خلال نموذج التواصل في الموقع، أو الاتصال بالعيادة مباشرة، أو مراسلتنا عبر واتساب. سنؤكد موعدك ونرسل لك موقع العيادة.","en":"You can book through the contact form on this website, call the clinic directly or send us a message on WhatsApp. We will confirm your appointment and send you the clinic location."}'::jsonb, true, 0),
  ('7be72c97-a49e-4845-aab6-1de78df0ad49', 'home', '{"ar":"ماذا أُحضر معي في الاستشارة الأولى؟","en":"What should I bring to my first consultation?"}'::jsonb, '{"ar":"يُرجى إحضار التقارير الطبية السابقة، ونتائج التحاليل الحديثة، وأشعة السونار أو الأشعة المقطعية، وقائمة بالأدوية التي تتناولها بانتظام.","en":"Please bring any previous medical reports, recent lab results, ultrasound or CT scans, and a list of the medications you take regularly."}'::jsonb, true, 1),
  ('4157bf1b-4294-4395-a5f8-821dac1c30b0', 'home', '{"ar":"كم تستغرق فترة التعافي بعد عمليات المناظير؟","en":"How long is recovery after laparoscopic surgery?"}'::jsonb, '{"ar":"يمشي معظم المرضى في يوم العملية نفسه، ويغادرون المستشفى خلال 24 ساعة، ويعودون إلى أنشطتهم اليومية الخفيفة خلال أسبوع. وتختلف المدة حسب نوع العملية والحالة الصحية العامة.","en":"Most patients walk on the same day, go home within 24 hours and return to light daily activities within one week. Recovery time varies with the procedure and your general health."}'::jsonb, true, 2),
  ('f2f67131-fc91-4c61-ab2b-af9ac76328c8', 'home', '{"ar":"هل تترك العملية ندوبًا واضحة؟","en":"Will the surgery leave visible scars?"}'::jsonb, '{"ar":"تعتمد جراحات المناظير على فتحات صغيرة بين 5 و10 ملم تتلاشى عادةً لتصبح بالكاد مرئية خلال أشهر، ونحرص على وضعها في الثنيات الطبيعية للجلد كلما أمكن.","en":"Laparoscopic surgery uses incisions of 5–10 mm that usually fade to barely visible marks within months. Where possible, incisions are placed in natural skin creases."}'::jsonb, true, 3),
  ('0194403f-935d-430a-a96b-01d728959f7f', 'services', '{"ar":"هل جراحة المناظير أكثر أمانًا من الجراحة المفتوحة؟","en":"Is laparoscopic surgery safer than open surgery?"}'::jsonb, '{"ar":"بالنسبة لمعظم المرضى المناسبين لها، تقل مع جراحة المناظير مخاطر التهاب الجرح والفتق الجراحي، ويكون الألم أقل والتعافي أسرع. ويعتمد الأسلوب الأنسب لك على حالتك وتاريخك المرضي، وهو ما نقيّمه خلال الاستشارة.","en":"For most suitable patients, laparoscopic surgery carries a lower risk of wound infection and incisional hernia, causes less pain and allows a faster recovery. The best approach for you depends on your condition and medical history, which we assess at consultation."}'::jsonb, true, 0),
  ('52129899-f6c8-43f3-a538-391662516666', 'services', '{"ar":"كم يومًا سأبقى في المستشفى؟","en":"How long will I stay in hospital?"}'::jsonb, '{"ar":"كثير من العمليات، مثل علاج البواسير بالليزر ومعظم عمليات الفتق، تُجرى في اليوم نفسه. ويحتاج استئصال المرارة بالمنظار عادةً إلى ليلة واحدة، بينما تتطلب جراحة الغدة الدرقية ليلة إلى ليلتين.","en":"Many procedures, such as laser hemorrhoid treatment and most hernia repairs, are day cases. Laparoscopic gallbladder removal usually needs one night, while thyroid surgery typically requires one to two nights."}'::jsonb, true, 1),
  ('3091537c-7c4d-4d82-ab58-85fd5b97f35c', 'services', '{"ar":"متى يمكنني العودة إلى العمل؟","en":"When can I return to work?"}'::jsonb, '{"ar":"يمكن عادةً العودة إلى الأعمال المكتبية خلال 5 إلى 10 أيام بعد معظم عمليات المناظير، بينما قد تتطلب الأعمال التي تشمل حمل أوزان ثقيلة من 3 إلى 4 أسابيع. وستحصل على خطة مخصصة قبل الخروج.","en":"Office work is usually possible within 5–10 days after most laparoscopic procedures. Jobs that involve heavy lifting may require 3–4 weeks. You will receive a personalised plan before discharge."}'::jsonb, true, 2),
  ('a7c0fd15-db57-4808-a3a1-7247c6e9c835', 'services', '{"ar":"هل يمكن أن يُشفى الفتق دون جراحة؟","en":"Can a hernia heal without surgery?"}'::jsonb, '{"ar":"لا. الفتق ضعف أو فتحة في جدار البطن ولا يُغلق من تلقاء نفسه. قد تخفف الأحزمة الطبية الأعراض لكنها لا تعالج السبب، كما أن تأخير الإصلاح يزيد خطر المضاعفات مثل اختناق الفتق.","en":"No. A hernia is a defect in the abdominal wall and does not close on its own. Support belts may ease symptoms but do not treat the cause, and delaying repair raises the risk of complications such as strangulation."}'::jsonb, true, 3),
  ('e5ab75b5-6ec5-4a59-ad08-6e81246f2ee0', 'services', '{"ar":"هل علاج البواسير بالليزر مؤلم؟","en":"Is laser hemorrhoid treatment painful?"}'::jsonb, '{"ar":"يسبب العلاج بالليزر ألمًا أقل بكثير من الجراحة التقليدية لعدم وجود جروح مفتوحة. ويحتاج معظم المرضى إلى مسكنات بسيطة فقط ويعودون إلى أنشطتهم خلال أيام قليلة.","en":"Laser treatment causes significantly less pain than traditional surgery because there are no open wounds. Most patients need only simple pain relief and return to daily activities within a few days."}'::jsonb, true, 4),
  ('2c6c08d6-3e24-4ac6-a45b-58337b1f99a0', 'services', '{"ar":"هل تؤثر جراحة الغدة الدرقية على الصوت؟","en":"Can thyroid surgery affect my voice?"}'::jsonb, '{"ar":"قد تحدث بحة مؤقتة في الصوت، لكن التغير الدائم نادر مع الجرّاح المتمرّس. ونستخدم جهاز مراقبة الأعصاب أثناء العملية وتقنية دقيقة لحماية أعصاب الحنجرة.","en":"Temporary hoarseness can occur, but permanent voice change is rare in experienced hands. We use intra-operative nerve monitoring and meticulous technique to protect the laryngeal nerves."}'::jsonb, true, 5),
  ('7d48e7c9-fa7a-4647-a3c2-cec7eed08e16', 'services', '{"ar":"ما الفحوصات المطلوبة قبل العملية؟","en":"What tests will I need before surgery?"}'::jsonb, '{"ar":"عادةً تحاليل الدم ورسم القلب والأشعة المتعلقة بحالتك. وقد يُطلب أيضًا تقييم من طبيب التخدير أو استشارة تخصصية بحسب العمر والحالة الصحية.","en":"Typically blood tests, an ECG and imaging relevant to your condition. Depending on your age and health, an anaesthesia assessment or specialist review may also be requested."}'::jsonb, true, 6),
  ('5ea12f52-aace-4b68-a118-d005656c48da', 'services', '{"ar":"هل يمكنني إرسال تقاريري قبل الحجز؟","en":"Can I send my reports before booking?"}'::jsonb, '{"ar":"نعم، يمكنك إرسال التقارير والأشعة عبر واتساب لمراجعة مبدئية، وسنرشدك إلى الخطوة التالية الأنسب.","en":"Yes. You can send your reports and scans via WhatsApp for an initial review, and we will advise you on the most appropriate next step."}'::jsonb, true, 7)
insert into public.admin_users (user_id)
